import type { KeyboardEvent } from 'react';
import { useIntl } from 'react-intl';

import { SubPillarCard } from 'components/SubPillarCard';

import { GENOME_PORTAL_URL } from '../../../constants';
import { StyledGenomePortalCard } from './ConnectSection.styles';

const handleNavigate = () => {
  window.location.assign(GENOME_PORTAL_URL);
};

const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
  if (event.key === 'Enter' || event.key === ' ' || event.key === 'Spacebar') {
    event.preventDefault();
    handleNavigate();
  }
};

export const GenomePortalCard = () => {
  const { formatMessage } = useIntl();

  return (
    <StyledGenomePortalCard
      data-testid="genome-portal-card"
      role="button"
      tabIndex={0}
      onClick={handleNavigate}
      onKeyDown={handleKeyDown}
    >
      <SubPillarCard
        title={formatMessage({
          id: 'ConnectionsCreativity.Home.connect.genomePortal.title',
        })}
        description={formatMessage({
          id: 'ConnectionsCreativity.Home.connect.genomePortal.description',
        })}
      />
    </StyledGenomePortalCard>
  );
};
